class LFUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.data = new Map();      // key -> [value, frequency]
        this.groups = new Map();    // frequency -> Map(key -> null), insertion-ordered
        this.minFrequency = 0;
    }

    _promote(key) {
        const [value, frequency] = this.data.get(key);
        const bucket = this.groups.get(frequency);
        bucket.delete(key);
        if (bucket.size === 0) {
            this.groups.delete(frequency);
            if (this.minFrequency === frequency) this.minFrequency += 1;
        }
        const newFrequency = frequency + 1;
        this.data.set(key, [value, newFrequency]);
        if (!this.groups.has(newFrequency)) this.groups.set(newFrequency, new Map());
        this.groups.get(newFrequency).set(key, null);
    }

    get(key) {
        if (!this.data.has(key)) return -1;
        const value = this.data.get(key)[0];
        this._promote(key);
        return value;
    }

    put(key, value) {
        if (this.capacity === 0) return;
        if (this.data.has(key)) {
            const frequency = this.data.get(key)[1];
            this.data.set(key, [value, frequency]);
            this._promote(key);
            return;
        }
        if (this.data.size === this.capacity) {
            const bucket = this.groups.get(this.minFrequency);
            const evictedKey = bucket.keys().next().value;
            bucket.delete(evictedKey);
            if (bucket.size === 0) this.groups.delete(this.minFrequency);
            this.data.delete(evictedKey);
        }
        this.data.set(key, [value, 1]);
        if (!this.groups.has(1)) this.groups.set(1, new Map());
        this.groups.get(1).set(key, null);
        this.minFrequency = 1;
    }
}

