from collections import OrderedDict, defaultdict

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.data = {}  # key -> (value, frequency)
        self.groups = defaultdict(OrderedDict)  # frequency -> ordered keys
        self.min_frequency = 0

    def _promote(self, key: int) -> None:
        value, frequency = self.data[key]
        del self.groups[frequency][key]
        if not self.groups[frequency]:
            del self.groups[frequency]
            if self.min_frequency == frequency:
                self.min_frequency += 1

        new_frequency = frequency + 1
        self.data[key] = (value, new_frequency)
        self.groups[new_frequency][key] = None

    def get(self, key: int) -> int:
        if key not in self.data:
            return -1
        value = self.data[key][0]
        self._promote(key)
        return value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return

        if key in self.data:
            frequency = self.data[key][1]
            self.data[key] = (value, frequency)
            self._promote(key)
            return

        if len(self.data) == self.capacity:
            evicted_key, _ = self.groups[self.min_frequency].popitem(last=False)
            if not self.groups[self.min_frequency]:
                del self.groups[self.min_frequency]
            del self.data[evicted_key]

        self.data[key] = (value, 1)
        self.groups[1][key] = None
        self.min_frequency = 1
